(1253418, 160508, 18197, '<td valign="top">Well composed, lit, focused and post processed. Very nice job.</td>', 'Well composed, lit, focused and post processed. Very nice job.', '2005-03-28 02:09:03.000000', NULL, 1),
(1253420, 159324, 33672, '<td valign="top">Very eirie, Especially with the title.  Excellent work.</td>', 'Very eirie, Especially with the title.  Excellent work.', '2005-03-28 02:10:10.000000', NULL, 1),
