INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1262293, 160611, 32872, '<td valign="top">Wow, what an interesting photograph.  I''ve never seen anything like this.  The reflection looks eerie...I like it!<br/></td>', 'Wow, what an interesting photograph.  I''ve never seen anything like this.  The reflection looks eerie...I like it!', '2005-03-31 17:35:37.000000', NULL, 1),
